from scipy.optimize import least_squares
files=['train/A2_vref_op1.csv','train/A2_vref_op3.csv']
D=[load(f) for f in files]
names=['XL','mq','kiv','mp','TPf','TQf','TVf']
def mk(kpv):
    def res(x):
        p=dict(zip(names,x)); p['kpv']=kpv; out=[]
        for d in D:
            P,Q=sim(p,d); out.append(P-d.active_power_pu.values); out.append(Q-d.reactive_power_pu.values)
        return np.concatenate(out)
    return res
